const panels={
env:{caption:'The right environment should never be a guessing game.',html:document.querySelector('#demo-panel').innerHTML},
blast:{caption:'A clearer picture before you grant permission.',html:'<div class="terminal-prompt"><span>❯</span> Clean up the build directory.</div><div class="terminal-row"><b>⏺ Bash</b><code>rm -rf ./build</code></div><div class="badge amber">PERMISSION REQUEST · IMPACT PREVIEW</div><div class="terminal-row"><b>💥 rm -r</b><code>⚠ 1,117 not in git (1,100 gitignored)<br>1,204 files · 48 MB</code></div><div class="terminal-row"><code>Details in the Blast radius pane.<br>Your permission decision stays yours.</code></div>'},
footprint:{caption:'A live picture of the actions in your session.',html:'<div class="terminal-prompt"><span>❯</span> /map</div><div class="terminal-row"><b class="amber-text">CHANGED (1)</b><code>Kubernetes prod-eks · namespace web<br>└ deployment api<br>&nbsp; rollout restart, worked</code></div><div class="terminal-row"><b>MAY HAVE CHANGED (1)</b><code>AWS account 123456789012 · global<br>└ sts Deploy · assume-role, worked</code></div><div class="terminal-row"><b>LOOKED AT (24)</b><code>ec2, lambda, pods, deployments, services</code></div>'},
brain:{caption:'Keep the lesson. Skip the rediscovery.',html:'<div class="terminal-prompt"><span>❯</span> Have we solved this before?</div><div class="terminal-row"><b>01 · Capture</b><code>Session takeaways saved to raw/</code></div><div class="terminal-row"><b>02 · Compile</b><code>Lessons organized into wiki pages</code></div><div class="terminal-row"><b>03 · Recall</b><code>Prompt keywords match relevant knowledge.<br>Bring the right page into the next session.</code></div><span class="badge green">Markdown + JSONL · your Git repo</span>'}
};
const tabs=[...document.querySelectorAll('[data-demo]')];
function showDemo(tab){tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});const panel=panels[tab.dataset.demo];document.querySelector('#demo-panel').innerHTML=panel.html;document.querySelector('#demo-panel').setAttribute('aria-labelledby',tab.id);document.querySelector('#demo-caption').textContent=panel.caption;}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>showDemo(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();tabs[next].focus();showDemo(tabs[next]);}})});
const select=document.querySelector('#plugin-select');
select.addEventListener('change',()=>{document.querySelector('#install-command').textContent='/plugin marketplace add aqaurius6666/claude-marketplace\n/plugin install '+select.value+'@aqaurius6666';document.querySelector('#install-note').textContent=select.value==='2brain'?'Repository access required. After installing, follow the 2brain README to scaffold your knowledge directory and configure capture and optional scheduled maintenance.':(select.value==='footprint'?'Repository access required. ':'')+'Enable function hooks with CLAUDE_CODE_ENABLE_FUNCTION_HOOKS=1 when starting Claude Code. See the plugin’s README for Desktop setup.';document.querySelector('#copy-status').textContent='';});
document.querySelector('#copy-button').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText(document.querySelector('#install-command').textContent);status.textContent='Installation commands copied.';}catch{status.textContent='Copy unavailable. Select and copy the commands above.'}});
